package org.jfree.chart.imagemap;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StandardToolTipTagFragmentGenerator.
 */
public class StandardToolTipTagFragmentGenerator_generateToolTipFragment_TriageGen2Test {

    private StandardToolTipTagFragmentGenerator generator;

    @Before
    public void setUp() {
        generator = new StandardToolTipTagFragmentGenerator();
    }

    @Test
    public void testGenerateToolTipFragment_withNormalText() {
        String input = "Hello World";
        String expected = " title=\"Hello World\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tooltip fragment should be correctly formatted for normal text.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withEmptyString() {
        String input = "";
        String expected = " title=\"\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tooltip fragment should handle empty strings correctly.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withNull() {
        // Note: Based on the implementation, passing null will result in " title=\"null\" alt=\"\""
        // because of string concatenation behavior in Java.
        String input = null;
        String expected = " title=\"null\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tooltip fragment should handle null input by converting it to the string 'null'.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withSpecialCharacters() {
        String input = "Value > 10 & < 20";
        String expected = " title=\"Value > 10 & < 20\" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tooltip fragment should preserve special characters within the quotes.", expected, actual);
    }

    @Test
    public void testGenerateToolTipFragment_withWhitespace() {
        String input = "   ";
        String expected = " title=\"   \" alt=\"\"";
        String actual = generator.generateToolTipFragment(input);
        assertEquals("The tooltip fragment should preserve whitespace.", expected, actual);
    }
}
